namespace{
int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

Document fixture(){auto d=empty_document("selection-menu-document","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;Object shape;shape.id="shape";shape.name="Original";shape.source=default_primitive("shape-source","nect.shape.rectangle");shape.source->parameters.at("width").literal=80;shape.source->parameters.at("height").literal=60;shape.source->parameters.at("center_x").literal=320;shape.source->parameters.at("center_y").literal=240;auto fill=default_operation("shape-fill","nect.paint.fill");fill.parameters.at("r").literal=1;fill.parameters.at("g").literal=0;fill.parameters.at("b").literal=0;shape.stack={fill};auto peer=shape;peer.id="peer";peer.name="Peer";peer.source->id="peer-source";peer.stack.front().id="peer-fill";peer.stack.front().parameters.at("r").literal=0;peer.stack.front().parameters.at("b").literal=1;d.objects.emplace(shape.id,shape);d.objects.emplace(peer.id,peer);d.compositions.front().roots={shape.id,peer.id};return d;}

void flow(const QString& root,int mode){auto initial=fixture();valid(initial);auto current=initial;current.objects.at("shape").name="Current source";valid(current);Session base(initial);base.apply({Rename{"shape","Current source"}},0);check(base.document()==current&&base.revision()==1,"Entire base native/History BEFORE Window");auto foreign_initial=initial;foreign_initial.id="caller-selection-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("shape").name="Current source";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"shape","Current source"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Whole equal-counter caller Document with colliding ordered roots BEFORE Window");auto concurrent=base;concurrent.apply({Rename{"shape","Concurrent source"}},1);auto concurrent_doc=current;concurrent_doc.objects.at("shape").name="Concurrent source";valid(concurrent_doc);check(concurrent.document()==concurrent_doc,"Whole concurrent revision oracle BEFORE Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Complete independent busy preview BEFORE Window");auto reordered=current;reordered.compositions.front().roots={"peer","shape"};valid(reordered);auto committed=base;committed.apply({ReorderObjects{"comp","",{"peer","shape"}}},1);check(committed.document()==reordered,"Independent exact stable-root order command/native BEFORE Window");auto history=committed;history.undo(2);check(history.document()==current,"Whole stacking Undo BEFORE Window");history.redo(3);check(history.document()==reordered&&history.history()==committed.history(),"One History/full Redo BEFORE Window");auto expected=base;if(mode==0)expected=foreign;else if(mode==2)expected=concurrent;else if(mode==3)expected=busy;else if(mode==4)expected=committed;const auto expected_image=Canvas::render_artboard(expected.document(),"comp","art",1,false);check(expected_image.pixelColor(320,240)==(mode==4?QColor(Qt::red):QColor(Qt::blue)),"Independent literal overlapping-flat-fill center pixel BEFORE Window");const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());check(expected_image.save(prefix+"-expected-artboard.png"),"Independent source-bound expected paint image BEFORE Window");
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);w.host.session=base;w.host.edited();w.resize(1400,1050);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selection("shape","");events();const auto original_host=w.host.session_id;QString callback_error;int stages=0;QPointer<QMenu> root_menu;QTimer::singleShot(0,&w,[&]{try{root_menu=qobject_cast<QMenu*>(QApplication::activePopupWidget());check(root_menu&&root_menu->isVisible(),"Original shared Canvas selection popup visible");++stages;QAction* arrange=nullptr;for(auto* a:root_menu->actions())if(a->text()=="Arrange stacking order")arrange=a;check(arrange&&arrange->isEnabled()&&arrange->menu(),"Original existing stacking submenu enabled for exact selected stable root");if(mode==0)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=concurrent;else if(mode==3)w.host.session=busy;check(root_menu->grab().save(prefix+"-menu.png"),"Actual original menu before selection/caller handoff");if(mode==5){QTest::keyClick(root_menu,Qt::Key_Escape);return;}root_menu->setActiveAction(arrange);QTest::keyClick(root_menu,Qt::Key_Right);events();auto* submenu=arrange->menu();check(submenu->isVisible(),"Original stacking submenu opens through Qt key event");QAction* front=nullptr;for(auto* a:submenu->actions())if(a->text()=="Bring to front")front=a;check(front&&front->isEnabled(),"Original Bring to front command exact");submenu->setActiveAction(front);QTest::keyClick(submenu,Qt::Key_Return);}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(root_menu)root_menu->close();}});const QPoint position(12,12);QContextMenuEvent event(QContextMenuEvent::Mouse,position,w.canvas->mapToGlobal(position));QApplication::sendEvent(w.canvas,&event);events();check(callback_error.isEmpty()&&stages==1,"Original popup entry and chosen Qt key path complete without fixture exception");const auto observed=w.host.session;const auto status=w.statusBar()->currentMessage();write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());check(w.grab().save(prefix+"-window.png"),"Actual shared-menu result BEFORE Save");const auto observed_image=Canvas::render_artboard(observed.document(),"comp","art",1,false);check(observed_image.save(prefix+"-observed-artboard.png"),"Actual source-bound committed paint image BEFORE Save");QJsonObject v{{"mode",mode},{"status",status},{"document_equal",observed.document()==expected.document()},{"preview_equal",observed.preview_document()==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"paint_equal",observed_image==expected_image},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=3||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_object=="shape"&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=3}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable shared-menu whole readback BEFORE Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same(observed,expected);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool()&&v["paint_equal"].toBool(),"Whole caller view/identity/exact paint retained");if(mode!=3){w.host.save(prefix+"-saved.nect");w.host.flush();events();same(w.host.session,expected);check(read(prefix+"-saved.nect")==read(prefix+"-expected.nect")&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Complete menu/refusal native Save/snapshot");}w.close();events();}
}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);app.setStyle("Fusion");app.setStyleSheet(application_style_sheet());std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<" original shared Canvas context menu/stacking keys; physical/clipboard/fonts NOT_RUN\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_SELECTION_MENU_DOCUMENT_ROOT"),root=requested.isEmpty()?temp.path():requested;int failures=0;for(int mode=0;mode<6;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Selection menu Document cases failed: "+std::to_string(failures));std::cout<<"PASS Selection menu Document "<<checks<<" checks\n";QTest::qWait(300);return 0;}catch(const std::exception& e){std::cerr<<"FAIL Selection menu Document "<<e.what()<<" after "<<checks<<" checks\n";QTest::qWait(300);return 1;}}
